const db = prisma as unknown as ExtendedPrismaClient;

/**
 * Dynamic lease duration for database-backed concurrency locking on IpDailyRevenueJobRun.
 * Workers maintain this lease via active heartbeats during execution.
 * A crashed worker is safely recovered after 60 seconds of silence, while long-running jobs
 * refresh their heartbeat throughout processing and never expire prematurely.
 */
export const LEASE_DURATION_MS = 60 * 1000; // 60 seconds lease window with continuous heartbeat
export const LEASE_TIMEOUT_MS = LEASE_DURATION_MS;

/**
 * FNV-1a 32-bit hash function.
 * Converts any string into a stable 32-bit signed integer for PostgreSQL advisory locks (int4).
 */
export function hashStringToInt(str: string): number {
  let hash = 2166136261;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash | 0;
}

/**
 * Safe PostgreSQL advisory lock acquisition helper.
 * Enforces fail-closed semantics: if the query fails or returns an unexpected shape,
 * it returns success: false with an explicit error rather than silently continuing.
 */
export async function tryAcquireAdvisoryLock(
  client: { $queryRaw: typeof prisma.$queryRaw },
  key1: number,
  key2: number
): Promise<{ success: boolean; acquired: boolean; error?: string }> {
  try {
    const rows = await client.$queryRaw<Array<{ acquired: boolean | null }>>`
      SELECT pg_try_advisory_xact_lock(${key1}, ${key2}) AS acquired
    `;

    if (!Array.isArray(rows) || rows.length === 0 || rows[0]?.acquired === undefined || rows[0]?.acquired === null) {
      return {
        success: false,
        acquired: false,
        error: 'Unexpected advisory lock query result shape from database',
      };
    }

    return {
      success: true,
      acquired: Boolean(rows[0].acquired),
    };
  } catch (err: any) {
    return {
      success: false,
      acquired: false,
      error: `Database advisory lock execution error: ${err.message || String(err)}`,
    };
  }
}

/**
 * Rounds a number to exactly two decimal places using EPSILON to avoid floating-point drift.
 */
export const round2 = (num: number): number => {
  return Math.round((num + Number.EPSILON) * 100) / 100;
};

/**
 * Safe conversion to Prisma.Decimal to ensure exact financial arithmetic without float drift.
 */
export const toDecimal = (val: unknown): Prisma.Decimal => {
  if (val === null || val === undefined || val === '') return new Prisma.Decimal(0);
  if (val instanceof Prisma.Decimal) return val;
  return new Prisma.Decimal(String(val));
};

/**
 * Derives the IST (Asia/Kolkata, UTC+5:30) calendar date as a UTC midnight Date.
 * Normalizes input so any time component is eliminated and PostgreSQL @db.Date representation matches.
 */
export const getIstBusinessDate = (date: Date): Date => {
  const istOffsetMs = (5 * 60 + 30) * 60 * 1000;
  const istTime = new Date(date.getTime() + istOffsetMs);
  return new Date(Date.UTC(istTime.getUTCFullYear(), istTime.getUTCMonth(), istTime.getUTCDate()));
};

/**
 * Returns the previous completed IST calendar date as UTC midnight.
 * e.g., On 2026-10-31 00:05 AM IST, returns 2026-10-30T00:00:00.000Z.
 */
export const getPreviousCompletedIstDate = (referenceDate: Date = new Date()): Date => {
  const istOffsetMs = (5 * 60 + 30) * 60 * 1000;
  const istTime = new Date(referenceDate.getTime() + istOffsetMs);
  return new Date(Date.UTC(istTime.getUTCFullYear(), istTime.getUTCMonth(), istTime.getUTCDate() - 1));
};

/**
 * Formats a Date into 'YYYY-MM-DD' in UTC.
 */
export const formatIstDate = (date: Date): string => {
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, '0');
  const d = String(date.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
};

/**
 * Parses a 'YYYY-MM-DD' string into a UTC midnight Date.
 */
export const parseIstDateString = (dateStr: string): Date => {
  if (typeof dateStr !== 'string') {
    throw new ApiError(400, 'Invalid date format. Expected YYYY-MM-DD');
  }
  const match = dateStr.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    throw new ApiError(400, 'Invalid date format. Expected YYYY-MM-DD');
  }
  const year = Number(match[1]);
  const month = Number(match[2]) - 1;
  const day = Number(match[3]);
  const d = new Date(Date.UTC(year, month, day));
  if (d.getUTCFullYear() !== year || d.getUTCMonth() !== month || d.getUTCDate() !== day) {
    throw new ApiError(400, 'Invalid calendar date');
  }
  return d;
};

/**
 * Bounded concurrency helper for parallel processing.
 * Validates concurrency strictly as a positive integer to prevent silent failures or starvation.
 */
export async function pMap<T, R>(
  items: T[],
  fn: (item: T) => Promise<R>,
  concurrency: number = 3
): Promise<R[]> {
  if (!Number.isInteger(concurrency) || concurrency <= 0) {
    throw new ApiError(400, `Invalid concurrency: ${concurrency}. Concurrency must be a positive integer.`);
  }

  if (items.length === 0) return [];

  const results: R[] = new Array(items.length);
  let currentIndex = 0;

  const workers = Array.from({ length: Math.min(concurrency, items.length) }, async () => {
    while (currentIndex < items.length) {
      const index = currentIndex++;
      results[index] = await fn(items[index]!);
    }
  });

  await Promise.all(workers);
  return results;
}

