/**
 * Aggregates daily game-wise revenue for a single IP Party on a specific business date.
 * Primary source of truth: TransactionSplit.
 *
 * Execution Order & Atomicity:
 * 1. Transaction-level PostgreSQL advisory lock on (ipOrganizationId, businessDate) is acquired FIRST,
 *    before reading any source splits or diagnostic counts.
 * 2. If called as part of a scheduled job, verifies the worker's fencing leaseToken inside the transaction.
 * 3. Reads source data and diagnostic counts strictly within the locked transaction, guaranteeing a consistent view.
 * 4. Tenant isolation is enforced: splits with missing relations or games registered to another party are diagnosed
 *    and excluded from financial totals without double-counting.
 * 5. Stale snapshots are deleted and active snapshots upserted within the same transaction.
 * 6. Preserves collected diagnostic counts in the return value even if a later write fails.
 */
export const aggregateIpPartyDailyRevenue = async (
  ipOrganizationId: string,
  businessDateInput: Date,
  jobContext?: { jobRunId: string; leaseToken: string }
): Promise<PartyDailyAggregationResult> => {
  const businessDate = getIstBusinessDate(businessDateInput);

  let splitsConsidered = 0;
  let resolvedSplitsCount = 0;
  let unresolvedSplitsCount = 0;
  let missingGameAttributionCount = 0;
  let inconsistentGameAttributionCount = 0;
  let recordsUpserted = 0;
  const gameSnapshots: GameAggregationSnapshot[] = [];

  try {
    return await db.$transaction(async (tx) => {
      // 1. Acquire per-party, per-date advisory lock at the VERY START of the transaction
      const lockKey1 = hashStringToInt('ip_daily_agg');
      const lockKey2 = hashStringToInt(`${ipOrganizationId}:${formatIstDate(businessDate)}`);

      const lockRes = await tryAcquireAdvisoryLock(tx, lockKey1, lockKey2);
      if (!lockRes.success) {
        throw new ApiError(500, `Advisory lock failure: ${lockRes.error}`);
      }
      if (!lockRes.acquired) {
        throw new ApiError(
          409,
          `LOCK_CONFLICT: Another aggregation or reconciliation is actively processing IP Party ${ipOrganizationId} on ${formatIstDate(
            businessDate
          )}`
        );
      }

      // 2. Fencing check: if running as part of a batched job run, verify worker lease is still active
      if (jobContext) {
        const now = new Date();
        const activeJob = await tx.ipDailyRevenueJobRun.findFirst({
          where: {
            id: jobContext.jobRunId,
            status: 'RUNNING' as any,
            leaseToken: jobContext.leaseToken,
            leaseExpiresAt: { gt: now },
          },
          select: { id: true },
        });

        if (!activeJob) {
          throw new ApiError(
            409,
            `FENCING_REJECTED: Job run ${jobContext.jobRunId} lease expired, was replaced, or is not in RUNNING status. Worker cannot persist snapshots.`
          );
        }
      }

      // 3. READ SOURCE DATA INSIDE THE TRANSACTION (Consistent source data view)
      // A. Count unresolved splits
      unresolvedSplitsCount = await tx.transactionSplit.count({
        where: {
          isIpTransaction: true,
          ipOrganizationId,
          businessDate,
          status: { not: 'RESOLVED' as any },
        },
      });

      // B. Count resolved splits missing ipGameId
      const missingIpGameIdCount = await tx.transactionSplit.count({
        where: {
          isIpTransaction: true,
          ipOrganizationId,
          businessDate,
          status: 'RESOLVED' as any,
          ipGameId: null,
        },
      });

      // C. Query all resolved splits with non-null ipGameId
      const candidateSplits = await tx.transactionSplit.findMany({
        where: {
          isIpTransaction: true,
          ipOrganizationId,
          businessDate,
          status: 'RESOLVED' as any,
          ipGameId: { not: null },
        },
        select: {
          id: true,
          ipGameId: true,
          grossAmount: true,
          gstAmount: true,
          pgFeeAmount: true,
          distributorShare: true,
          partnerShare: true,
          companyShare: true,
          ipShare: true,
          kioskAssignmentId: true,
          kioskAssignment: {
            select: {
              kioskId: true,
            },
          },
          ipGame: {
            select: {
              id: true,
              organizationId: true,
              gameIdentifier: true,
              displayName: true,
            },
          },
        },
      });

      let danglingGameCount = 0;
      let mismatchedTenantCount = 0;
      const overallDistinctKiosks = new Set<string>();
      let partyGrossRevenue = new Prisma.Decimal(0);
      let partyGstAmount = new Prisma.Decimal(0);
      let partyPgFeeAmount = new Prisma.Decimal(0);
      let partyNetworkShare = new Prisma.Decimal(0);
      let partyCompanyShareBeforeRoyalty = new Prisma.Decimal(0);
      let partyIpRoyaltyShare = new Prisma.Decimal(0);

      const gameGroups = new Map<
        string,
        {
          ipGameId: string;
          gameIdentifier: string;
          gameDisplayName: string;
          distinctKiosks: Set<string>;
          grossRevenue: Prisma.Decimal;
          gstAmount: Prisma.Decimal;
          pgFeeAmount: Prisma.Decimal;
          networkShare: Prisma.Decimal;
          companyShareBeforeRoyalty: Prisma.Decimal;
          ipRoyaltyShare: Prisma.Decimal;
        }
      >();

      for (const split of candidateSplits) {
        // Missing / dangling game relation
        if (!split.ipGame) {
          danglingGameCount++;
          continue;
        }

        // Mismatched tenant ownership: game registered to another party
        if (split.ipGame.organizationId !== ipOrganizationId) {
          mismatchedTenantCount++;
          continue;
        }

        resolvedSplitsCount++;

        const gameIdentifier = split.ipGame.gameIdentifier || 'unknown-game';
        const gameDisplayName = split.ipGame.displayName || gameIdentifier;

        let group = gameGroups.get(gameIdentifier);
        if (!group) {
          group = {
            ipGameId: split.ipGameId!,
            gameIdentifier,
            gameDisplayName,
            distinctKiosks: new Set<string>(),
            grossRevenue: new Prisma.Decimal(0),
            gstAmount: new Prisma.Decimal(0),
            pgFeeAmount: new Prisma.Decimal(0),
            networkShare: new Prisma.Decimal(0),
            companyShareBeforeRoyalty: new Prisma.Decimal(0),
            ipRoyaltyShare: new Prisma.Decimal(0),
          };
          gameGroups.set(gameIdentifier, group);
        }

        if (split.kioskAssignment?.kioskId) {
          group.distinctKiosks.add(split.kioskAssignment.kioskId);
          overallDistinctKiosks.add(split.kioskAssignment.kioskId);
        }

        const gross = toDecimal(split.grossAmount);
        const gst = toDecimal(split.gstAmount);
        const pg = toDecimal(split.pgFeeAmount);
        const distShare = toDecimal(split.distributorShare);
        const partShare = toDecimal(split.partnerShare);
        const netw = distShare.add(partShare);
        const company = toDecimal(split.companyShare);
        const ipRoyalty = toDecimal(split.ipShare);

        group.grossRevenue = group.grossRevenue.add(gross);
        group.gstAmount = group.gstAmount.add(gst);
        group.pgFeeAmount = group.pgFeeAmount.add(pg);
        group.networkShare = group.networkShare.add(netw);
        group.companyShareBeforeRoyalty = group.companyShareBeforeRoyalty.add(company);
        group.ipRoyaltyShare = group.ipRoyaltyShare.add(ipRoyalty);

        partyGrossRevenue = partyGrossRevenue.add(gross);
        partyGstAmount = partyGstAmount.add(gst);
        partyPgFeeAmount = partyPgFeeAmount.add(pg);
        partyNetworkShare = partyNetworkShare.add(netw);
        partyCompanyShareBeforeRoyalty = partyCompanyShareBeforeRoyalty.add(company);
        partyIpRoyaltyShare = partyIpRoyaltyShare.add(ipRoyalty);
      }

      missingGameAttributionCount = missingIpGameIdCount + danglingGameCount;
      inconsistentGameAttributionCount = mismatchedTenantCount;
      splitsConsidered =
        resolvedSplitsCount +
        unresolvedSplitsCount +
        missingGameAttributionCount +
        inconsistentGameAttributionCount;

      // 4. ATOMIC PERSISTENCE & STALE SNAPSHOT CLEANUP
      const activeGameIdentifiers = Array.from(gameGroups.keys());

      if (activeGameIdentifiers.length > 0) {
        await tx.ipDailyGameRevenue.deleteMany({
          where: {
            organizationId: ipOrganizationId,
            businessDate,
            gameIdentifier: { notIn: activeGameIdentifiers },
          },
        });
      } else {
        await tx.ipDailyGameRevenue.deleteMany({
          where: {
            organizationId: ipOrganizationId,
            businessDate,
          },
        });
      }

      for (const group of Array.from(gameGroups.values())) {
        const snapshot: GameAggregationSnapshot = {
          ipGameId: group.ipGameId,
          gameIdentifier: group.gameIdentifier,
          gameDisplayName: group.gameDisplayName,
          kioskCount: group.distinctKiosks.size,
          grossRevenue: group.grossRevenue.toFixed(2),
          gstAmount: group.gstAmount.toFixed(2),
          pgFeeAmount: group.pgFeeAmount.toFixed(2),
          networkShare: group.networkShare.toFixed(2),
          companyShareBeforeRoyalty: group.companyShareBeforeRoyalty.toFixed(2),
          ipRoyaltyShare: group.ipRoyaltyShare.toFixed(2),
        };

        gameSnapshots.push(snapshot);

        await tx.ipDailyGameRevenue.upsert({
          where: {
            organizationId_businessDate_gameIdentifier: {
              organizationId: ipOrganizationId,
              businessDate,
              gameIdentifier: group.gameIdentifier,
            },
          },
          update: {
            ipGameId: group.ipGameId,
            gameDisplayName: group.gameDisplayName,
            kioskCount: group.distinctKiosks.size,
            grossRevenue: group.grossRevenue.toFixed(2),
            gstAmount: group.gstAmount.toFixed(2),
            pgFeeAmount: group.pgFeeAmount.toFixed(2),
            networkShare: group.networkShare.toFixed(2),
            companyShareBeforeRoyalty: group.companyShareBeforeRoyalty.toFixed(2),
            ipRoyaltyShare: group.ipRoyaltyShare.toFixed(2),
            updatedAt: new Date(),
          },
          create: {
            organizationId: ipOrganizationId,
            ipGameId: group.ipGameId,
            businessDate,
            gameIdentifier: group.gameIdentifier,
            gameDisplayName: group.gameDisplayName,
            kioskCount: group.distinctKiosks.size,
            grossRevenue: group.grossRevenue.toFixed(2),
            gstAmount: group.gstAmount.toFixed(2),
            pgFeeAmount: group.pgFeeAmount.toFixed(2),
            networkShare: group.networkShare.toFixed(2),
            companyShareBeforeRoyalty: group.companyShareBeforeRoyalty.toFixed(2),
            ipRoyaltyShare: group.ipRoyaltyShare.toFixed(2),
          },
        });
        recordsUpserted++;
      }

      // Persist or prune party-wide daily summary snapshot (guarantees snapshot-only GET queries)
      if (activeGameIdentifiers.length > 0) {
        await (tx as any).ipDailyPartySummary.upsert({
          where: {
            organizationId_businessDate: {
              organizationId: ipOrganizationId,
              businessDate,
            },
          },
          update: {
            kioskCount: overallDistinctKiosks.size,
            grossRevenue: partyGrossRevenue.toFixed(2),
            gstAmount: partyGstAmount.toFixed(2),
            pgFeeAmount: partyPgFeeAmount.toFixed(2),
            networkShare: partyNetworkShare.toFixed(2),
            companyShareBeforeRoyalty: partyCompanyShareBeforeRoyalty.toFixed(2),
            ipRoyaltyShare: partyIpRoyaltyShare.toFixed(2),
            updatedAt: new Date(),
          },
          create: {
            organizationId: ipOrganizationId,
            businessDate,
            kioskCount: overallDistinctKiosks.size,
            grossRevenue: partyGrossRevenue.toFixed(2),
            gstAmount: partyGstAmount.toFixed(2),
            pgFeeAmount: partyPgFeeAmount.toFixed(2),
            networkShare: partyNetworkShare.toFixed(2),
            companyShareBeforeRoyalty: partyCompanyShareBeforeRoyalty.toFixed(2),
            ipRoyaltyShare: partyIpRoyaltyShare.toFixed(2),
          },
        });
      } else {
        await (tx as any).ipDailyPartySummary.deleteMany({
          where: {
            organizationId: ipOrganizationId,
            businessDate,
          },
        });
      }

      // Persist or prune distinct daily game kiosks (enables exact monthly distinct kiosk counting without querying TransactionSplit)
      const kioskDelegate = (tx as any).ipDailyGameKiosk;
      if (!kioskDelegate) {
        throw new ApiError(
          500,
          `IpDailyGameKiosk persistence delegate is unavailable. Daily distinct kiosk tracking is required for monthly kiosk counting.`
        );
      }

      await kioskDelegate.deleteMany({
        where: {
          organizationId: ipOrganizationId,
          businessDate,
        },
      });

      if (activeGameIdentifiers.length > 0) {
        const kioskEntries: {
          organizationId: string;
          businessDate: Date;
          gameIdentifier: string;
          kioskId: string;
        }[] = [];

        for (const group of Array.from(gameGroups.values())) {
          for (const kioskId of Array.from(group.distinctKiosks)) {
            kioskEntries.push({
              organizationId: ipOrganizationId,
              businessDate,
              gameIdentifier: group.gameIdentifier,
              kioskId,
            });
          }
        }

        if (kioskEntries.length > 0) {
          await kioskDelegate.createMany({
            data: kioskEntries,
            skipDuplicates: true,
          });
        }
      }

      return {
        ipOrganizationId,
        businessDate,
        splitsConsidered,
        resolvedSplitsCount,
        unresolvedSplitsCount,
        missingGameAttributionCount,
        inconsistentGameAttributionCount,
        recordsUpserted,
        gameSnapshots,
        success: true,
      };
    });
  } catch (err: any) {
    // PRESERVE DIAGNOSTIC COUNTS ON FAILURE
    return {
      ipOrganizationId,
      businessDate,
      splitsConsidered,
      resolvedSplitsCount,
      unresolvedSplitsCount,
      missingGameAttributionCount,
      inconsistentGameAttributionCount,
      recordsUpserted: 0,
      gameSnapshots: [],
      success: false,
      error: err.message || String(err),
    };
  }
};

/**
 * Renews the active heartbeat on a job run using an atomic conditional database update.
 * Atomically verifies:
 * 1. Job ID matches.
 * 2. Status is RUNNING.
 * 3. Lease token matches.
 * 4. Lease has not already expired (leaseExpiresAt > now).
 *
 * Only considers renewal successful when exactly one record was updated.
 */
export async function renewJobHeartbeat(
  jobRunId: string,
  leaseToken: string
): Promise<{ success: boolean; reason?: string }> {
  try {
    const now = new Date();
    const newExpiry = new Date(now.getTime() + LEASE_DURATION_MS);

    const result = await db.ipDailyRevenueJobRun.updateMany({
      where: {
        id: jobRunId,
        status: 'RUNNING' as any,
        leaseToken,
        leaseExpiresAt: { gt: now },
      },
      data: {
        lastHeartbeatAt: now,
        leaseExpiresAt: newExpiry,
      },
    });

    if (result.count === 1) {
      return { success: true };
    }

    // Renewal failed; perform a diagnostic check to determine exact failure reason
    const existing = await db.ipDailyRevenueJobRun.findUnique({
      where: { id: jobRunId },
      select: { status: true, leaseToken: true, leaseExpiresAt: true },
    });

    if (!existing) {
      return { success: false, reason: 'Job record not found' };
    }
    if (existing.status !== 'RUNNING') {
      return { success: false, reason: `Job is no longer RUNNING (current status: ${existing.status})` };
    }
    if (existing.leaseToken !== leaseToken) {
      return { success: false, reason: 'Lease token was revoked or replaced by another worker' };
    }
    if (existing.leaseExpiresAt && existing.leaseExpiresAt <= now) {
      return { success: false, reason: 'Lease expired before heartbeat renewal' };
    }

    return { success: false, reason: 'Conditional update did not match active lease' };
  } catch (err: any) {
    console.error('[Daily Revenue Aggregation] Failed to renew heartbeat:', err);
    return { success: false, reason: err.message || String(err) };
  }
}

/**
 * Atomically and conditionally updates terminal job status.
 * Fencing safeguard: a stale worker whose lease expired or was replaced cannot overwrite
 * terminal status or mark a newer worker FAILED.
 * Verifies:
 * 1. Job ID matches.
 * 2. Status is RUNNING.
 * 3. Lease token matches.
 * 4. Lease has not already expired.
 */
export async function finalizeJobStatus(
  jobRunId: string,
  leaseToken: string,
  finalStatus: 'COMPLETED' | 'PARTIALLY_COMPLETED' | 'FAILED',
  metrics: {
    partiesProcessed: number;
    batchesTotal: number;
    batchesSuccessful: number;
    batchesFailed: number;
    splitsConsidered: number;
    unresolvedSplitsExcluded: number;
    missingGameAttributionCount: number;
    inconsistentGameAttributionCount?: number;
    recordsCreatedOrUpdated: number;
    errorMessage?: string | null;
  }
): Promise<{ finalized: boolean; reason?: string }> {
  try {
    const now = new Date();

    const result = await db.ipDailyRevenueJobRun.updateMany({
      where: {
        id: jobRunId,
        status: 'RUNNING' as any,
        leaseToken,
        leaseExpiresAt: { gt: now },
      },
      data: {
        status: finalStatus as any,
        completedAt: now,
        partiesProcessed: metrics.partiesProcessed,
        batchesTotal: metrics.batchesTotal,
        batchesSuccessful: metrics.batchesSuccessful,
        batchesFailed: metrics.batchesFailed,
        splitsConsidered: metrics.splitsConsidered,
        unresolvedSplitsExcluded: metrics.unresolvedSplitsExcluded,
        missingGameAttributionCount: metrics.missingGameAttributionCount,
        recordsCreatedOrUpdated: metrics.recordsCreatedOrUpdated,
        errorMessage: metrics.errorMessage || null,
      },
    });

    if (result.count === 1) {
      return { finalized: true };
    }

    // Diagnostic check for why finalization did not match exactly 1 record
    const current = await db.ipDailyRevenueJobRun.findUnique({
      where: { id: jobRunId },
      select: { status: true, leaseToken: true, leaseExpiresAt: true },
    });

    if (!current) {
      return { finalized: false, reason: 'Job not found' };
    }
    if (current.status !== 'RUNNING') {
      return { finalized: false, reason: `Job is already in terminal status: ${current.status}` };
    }
    if (current.leaseToken !== leaseToken) {
      return { finalized: false, reason: 'Lease token replaced by another worker' };
    }
    if (current.leaseExpiresAt && current.leaseExpiresAt <= now) {
      return { finalized: false, reason: 'Lease expired before finalization' };
    }

    return { finalized: false, reason: 'Fencing check failed: atomic update did not match active lease' };
  } catch (err: any) {
    console.error('[Daily Revenue Aggregation] Failed to finalize job status:', err);
    return { finalized: false, reason: err.message || String(err) };
  }
}

/**
 * Acquires a database-backed lease/lock for the target businessDate on IpDailyRevenueJobRun.
 *
 * Concurrency Safety:
 * 1. Uses a PostgreSQL transaction advisory lock during check-and-create so multiple API instances
 *    cannot race when no RUNNING record exists. Fails closed on SQL execution error.
 * 2. Emits a unique leaseToken with an active leaseExpiresAt timestamp.
 * 3. Safely recovers from crashed workers after LEASE_DURATION_MS of silence by marking them FAILED.
 * 4. Workers continuously refresh their lease via renewJobHeartbeat() throughout execution.
 */
async function acquireJobRunLease(
  businessDate: Date,
  partiesDiscovered: number
): Promise<{ acquired: boolean; jobRunId?: string; leaseToken?: string; conflictReason?: string }> {
  return await db.$transaction(async (tx) => {
    // 1. Transaction-level advisory lock serializes check-and-create across instances
    const lockKey1 = hashStringToInt('ip_job_lock');
    const lockKey2 = hashStringToInt(formatIstDate(businessDate));
    const lockRes = await tryAcquireAdvisoryLock(tx, lockKey1, lockKey2);

    if (!lockRes.success) {
      throw new ApiError(500, `Advisory lock check error: ${lockRes.error}`);
    }

    if (!lockRes.acquired) {
      return {
        acquired: false,
        conflictReason: `Another worker is currently acquiring the aggregation lock for business date ${formatIstDate(
          businessDate
        )}`,
      };
    }

    // 2. Query existing RUNNING job
    const existing = await tx.ipDailyRevenueJobRun.findFirst({
      where: {
        businessDate,
        status: 'RUNNING',
      },
      orderBy: { startedAt: 'desc' },
    });

    if (existing) {
      const leaseExpiresAt = existing.leaseExpiresAt
        ? existing.leaseExpiresAt.getTime()
        : ((existing.metadata as any)?.leaseExpiresAt
          ? new Date((existing.metadata as any).leaseExpiresAt).getTime()
          : new Date(existing.startedAt).getTime() + LEASE_DURATION_MS);

      const now = Date.now();
      if (now < leaseExpiresAt) {
        return {
          acquired: false,
          conflictReason: `Another aggregation job (${existing.id}) is actively processing business date ${formatIstDate(
            businessDate
          )}. Active lease remaining: ${Math.round((leaseExpiresAt - now) / 1000)}s.`,
        };
      }

      // Previous worker crashed or hung; recover by marking old run FAILED
      console.warn(
        `[Daily Revenue Aggregation] Recovering from crashed/timed-out job run ${existing.id} for ${formatIstDate(
          businessDate
        )} (heartbeat expired)`
      );
      await tx.ipDailyRevenueJobRun.update({
        where: { id: existing.id },
        data: {
          status: 'FAILED',
          completedAt: new Date(),
          errorMessage: 'Worker lease/heartbeat expired (crashed worker recovered)',
        },
      });
    }

    // 3. Create new job run with active lease and heartbeat metadata
    const leaseToken = crypto.randomUUID();
    const now = new Date();
    const leaseExpiresAt = new Date(now.getTime() + LEASE_DURATION_MS);

    const newRun = await tx.ipDailyRevenueJobRun.create({
      data: {
        businessDate,
        status: 'RUNNING',
        partiesDiscovered,
        startedAt: now,
        leaseToken,
        leaseExpiresAt,
        lastHeartbeatAt: now,
        metadata: {
          leaseToken,
          leaseExpiresAt: leaseExpiresAt.toISOString(),
          lastHeartbeatAt: now.toISOString(),
        },
      },
    });

    return { acquired: true, jobRunId: newRun.id, leaseToken };
  });
}

/**
 * Orchestrator for Daily Revenue Aggregation across all registered IP Parties.
 *
 * Pipeline Stage:
 * 1. Transaction Sync
 * 2. Transaction Split Calculation
 * 3. Daily Revenue Aggregation (THIS SERVICE)
 */
export const runDailyRevenueAggregation = async (options?: {
  targetDate?: Date | undefined;
  lookbackDays?: number | undefined;
  batchSize?: number | undefined;
  maxConcurrency?: number | undefined;
}): Promise<DailyAggregationJobResult> => {
  const batchSize = options?.batchSize ?? 10;
  const maxConcurrency = options?.maxConcurrency ?? 3;
  const lookbackDays = options?.lookbackDays ?? 0;

  // 1. Validate configuration parameters strictly
  if (!Number.isInteger(batchSize) || batchSize <= 0) {
    throw new ApiError(400, `Invalid batchSize: ${batchSize}. batchSize must be a positive integer.`);
  }
  if (!Number.isInteger(maxConcurrency) || maxConcurrency <= 0) {
    throw new ApiError(400, `Invalid maxConcurrency: ${maxConcurrency}. maxConcurrency must be a positive integer.`);
  }
  if (!Number.isInteger(lookbackDays) || lookbackDays < 0) {
    throw new ApiError(400, `Invalid lookbackDays: ${lookbackDays}. lookbackDays must be a non-negative integer.`);
  }

  // 2. Normalize targetDate to IST calendar date at UTC midnight
  const rawTarget = options?.targetDate || getPreviousCompletedIstDate();
  const targetDate = getIstBusinessDate(rawTarget);

  console.log(
    `[Daily Revenue Aggregation] Initiating aggregation for business date: ${formatIstDate(
      targetDate
    )} (Lookback days: ${lookbackDays}, Batch size: ${batchSize}, Concurrency: ${maxConcurrency})...`
  );

  // 3. Discover all IP Parties
  const ipParties = await db.organization.findMany({
    where: { type: 'IP_PARTY' as any },
    select: { id: true, name: true },
    orderBy: { createdAt: 'asc' },
  });

  const partiesDiscovered = ipParties.length;

  // 4. Database-backed concurrency lock
  const leaseResult = await acquireJobRunLease(targetDate, partiesDiscovered);
  if (!leaseResult.acquired) {
    console.warn(`[Daily Revenue Aggregation] ${leaseResult.conflictReason}`);
    return {
      jobRunId: undefined,
      businessDate: targetDate,
      status: 'BLOCKED',
      partiesDiscovered,
      partiesProcessed: 0,
      batchesTotal: 0,
      batchesSuccessful: 0,
      batchesFailed: 0,
      splitsConsidered: 0,
      unresolvedSplitsExcluded: 0,
      missingGameAttributionCount: 0,
      inconsistentGameAttributionCount: 0,
      recordsCreatedOrUpdated: 0,
      errors: [leaseResult.conflictReason || 'Job concurrency lock active'],
    };
  }

  const jobRunId = leaseResult.jobRunId!;
  const leaseToken = leaseResult.leaseToken!;

  // 5. Determine dates to process (targetDate + lookback dates)
  const datesToProcess: Date[] = [targetDate];
  for (let i = 1; i <= lookbackDays; i++) {
    const pastDate = new Date(Date.UTC(targetDate.getUTCFullYear(), targetDate.getUTCMonth(), targetDate.getUTCDate() - i));
    datesToProcess.push(getIstBusinessDate(pastDate));
  }

  // 6. Partition IP Parties into batches
  const partyBatches: { id: string; name: string }[][] = [];
  for (let i = 0; i < ipParties.length; i += batchSize) {
    partyBatches.push(ipParties.slice(i, i + batchSize));
  }

  const batchesTotal = partyBatches.length * datesToProcess.length;

  let totalSplitsConsidered = 0;
  let totalUnresolvedSplitsExcluded = 0;
  let totalMissingGameAttribution = 0;
  let totalInconsistentGameAttribution = 0;
  let totalRecordsCreatedOrUpdated = 0;
  let partiesProcessed = 0;
  let batchesSuccessful = 0;
  let batchesFailed = 0;
  const errors: string[] = [];

  // Background continuous heartbeat renewal to keep lease refreshed during long batches
  const HEARTBEAT_INTERVAL_MS = 15000;
  let heartbeatFailureReason: string | null = null;

  const heartbeatTimer = setInterval(async () => {
    const renew = await renewJobHeartbeat(jobRunId, leaseToken);
    if (!renew.success) {
      heartbeatFailureReason = renew.reason || 'Periodic heartbeat renewal failed';
      clearInterval(heartbeatTimer);
    }
  }, HEARTBEAT_INTERVAL_MS);

  try {
    for (const bDate of datesToProcess) {
      for (const batch of partyBatches) {
        if (heartbeatFailureReason) {
          throw new ApiError(
            409,
            `Worker lease for job ${jobRunId} expired or superseded during batch processing: ${heartbeatFailureReason}. Aborting remaining batches.`
          );
        }

        // Heartbeat Renewal before batch execution
        const renewRes = await renewJobHeartbeat(jobRunId, leaseToken);
        if (!renewRes.success) {
          throw new ApiError(
            409,
            `Worker lease for job ${jobRunId} was revoked or superseded: ${renewRes.reason}. Aborting remaining batches.`
          );
        }

        try {
          // Pass jobContext so each per-party snapshot write verifies the active lease token inside its transaction
          const batchResults = await pMap(
            batch,
            async (party) => aggregateIpPartyDailyRevenue(party.id, bDate, { jobRunId, leaseToken }),
            maxConcurrency
          );

          let batchHadError = false;
          for (const res of batchResults) {
            if (!res.success) {
              batchHadError = true;
              errors.push(`Party ${res.ipOrganizationId} on ${formatIstDate(bDate)}: ${res.error}`);
            } else {
              partiesProcessed++;
              totalSplitsConsidered += res.splitsConsidered;
              totalUnresolvedSplitsExcluded += res.unresolvedSplitsCount;
              totalMissingGameAttribution += res.missingGameAttributionCount;
              totalInconsistentGameAttribution += res.inconsistentGameAttributionCount;
              totalRecordsCreatedOrUpdated += res.recordsUpserted;
            }
          }

          if (batchHadError) {
            batchesFailed++;
          } else {
            batchesSuccessful++;
          }
        } catch (batchErr: any) {
          batchesFailed++;
          errors.push(`Batch execution error on ${formatIstDate(bDate)}: ${batchErr.message || String(batchErr)}`);
        }
      }
    }

    const finalStatus: 'COMPLETED' | 'PARTIALLY_COMPLETED' | 'FAILED' =
      batchesTotal === 0 && partiesDiscovered === 0
        ? 'COMPLETED'
        : batchesFailed === 0
        ? 'COMPLETED'
        : batchesSuccessful > 0
        ? 'PARTIALLY_COMPLETED'
        : 'FAILED';

    // 7. Conditionally update Job Run record with terminal status and release lease
    await finalizeJobStatus(jobRunId, leaseToken, finalStatus, {
      partiesProcessed,
      batchesTotal,
      batchesSuccessful,
      batchesFailed,
      splitsConsidered: totalSplitsConsidered,
      unresolvedSplitsExcluded: totalUnresolvedSplitsExcluded,
      missingGameAttributionCount: totalMissingGameAttribution,
      inconsistentGameAttributionCount: totalInconsistentGameAttribution,
      recordsCreatedOrUpdated: totalRecordsCreatedOrUpdated,
      errorMessage: errors.length > 0 ? errors.join('; ') : null,
    });

    console.log(
      `[Daily Revenue Aggregation] Finished with status: ${finalStatus}. Parties processed: ${partiesProcessed}/${partiesDiscovered}, Snapshots created/updated: ${totalRecordsCreatedOrUpdated}, Unresolved excluded: ${totalUnresolvedSplitsExcluded}`
    );

    return {
      jobRunId,
      businessDate: targetDate,
      status: finalStatus,
      partiesDiscovered,
      partiesProcessed,
      batchesTotal,
      batchesSuccessful,
      batchesFailed,
      splitsConsidered: totalSplitsConsidered,
      unresolvedSplitsExcluded: totalUnresolvedSplitsExcluded,
      missingGameAttributionCount: totalMissingGameAttribution,
      inconsistentGameAttributionCount: totalInconsistentGameAttribution,
      recordsCreatedOrUpdated: totalRecordsCreatedOrUpdated,
      errors,
    };
  } catch (fatalError: any) {
    // Guaranteed terminal status logging conditional on active lease
    await finalizeJobStatus(jobRunId, leaseToken, 'FAILED', {
      partiesProcessed,
      batchesTotal,
      batchesSuccessful,
      batchesFailed,
      splitsConsidered: totalSplitsConsidered,
      unresolvedSplitsExcluded: totalUnresolvedSplitsExcluded,
      missingGameAttributionCount: totalMissingGameAttribution,
      inconsistentGameAttributionCount: totalInconsistentGameAttribution,
      recordsCreatedOrUpdated: totalRecordsCreatedOrUpdated,
      errorMessage: `Fatal unexpected error: ${fatalError.message || String(fatalError)}`,
    });

    throw fatalError;
  } finally {
    clearInterval(heartbeatTimer);
  }
};

/**
 * Reconciles daily revenue snapshots for a single IP Party across a date range.
 * Fully reports successes, failed dates, and error messages without silent failures.
 *
 * Input Validations:
 * - Rejects non-Date or invalid Date objects.
 * - Rejects endDate earlier than startDate.
 * - Verifies target organization exists and is of type IP_PARTY.
 */
export const reconcileIpPartyDailyRevenue = async (
  ipOrganizationId: string,
  startDateInput: Date,
  endDateInput: Date = startDateInput
): Promise<ReconciliationResult> => {
  if (!ipOrganizationId || typeof ipOrganizationId !== 'string') {
    throw new ApiError(400, 'Invalid IP organization ID');
  }

  // 1. Verify target organization is a registered IP Party
  const org = await db.organization.findUnique({
    where: { id: ipOrganizationId },
    select: { id: true, type: true },
  });

  if (!org || (org.type as any) !== 'IP_PARTY') {
    throw new ApiError(404, 'IP Party organization not found');
  }

  // 2. Validate date range
  if (!(startDateInput instanceof Date) || isNaN(startDateInput.getTime())) {
    throw new ApiError(400, 'Invalid start date');
  }
  if (!(endDateInput instanceof Date) || isNaN(endDateInput.getTime())) {
    throw new ApiError(400, 'Invalid end date');
  }

  const startDate = getIstBusinessDate(startDateInput);
  const finalDate = getIstBusinessDate(endDateInput);

  if (startDate.getTime() > finalDate.getTime()) {
    throw new ApiError(400, 'Reconciliation end date cannot be earlier than start date');
  }

  let currentDate = startDate;
  let datesProcessed = 0;
  let datesFailed = 0;
  let totalRecordsUpserted = 0;
  const failures: ReconciliationFailure[] = [];

  while (currentDate.getTime() <= finalDate.getTime()) {
    const dateStr = formatIstDate(currentDate);
    try {
      const res = await aggregateIpPartyDailyRevenue(ipOrganizationId, currentDate);
      if (res.success) {
        datesProcessed++;
        totalRecordsUpserted += res.recordsUpserted;
      } else {
        datesFailed++;
        failures.push({
          date: dateStr,
          error: res.error || 'Unknown aggregation error',
        });
      }
    } catch (err: any) {
      datesFailed++;
      failures.push({
        date: dateStr,
        error: err.message || String(err),
      });
    }

    currentDate = new Date(Date.UTC(currentDate.getUTCFullYear(), currentDate.getUTCMonth(), currentDate.getUTCDate() + 1));
  }

  return {
    datesProcessed,
    datesFailed,
    totalRecordsUpserted,
    failures,
    success: datesFailed === 0,
  };
};
